import { randomUUID } from 'crypto';
import { z } from 'zod';
import { ProjectRuntimeRecords } from '../storage/library/ProjectRuntimeRecords';
import {
  installationChannel,
  type InstallationChannel,
} from '../install/installationChannel';
import { existsSync, mkdirSync, readFileSync, unlinkSync } from 'fs';
import { dirname, join } from 'path';
import { createLogger } from '../utils/logger';
import { isPidAlive } from '../utils/pid';
import { errnoCode } from '../utils/errnoCode';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';

const log = createLogger('CliServerHandshake');

export const CLI_HANDSHAKE_VERSION = 1;

export type ServerHandshake = {
  version: typeof CLI_HANDSHAKE_VERSION;
  pid: number;
  rivetPort: number;
  projectPath: string;
  startedAt: string;
  sessionId: string | null;
  applyMode: 'embedded' | 'none';
  queueAccessToken: string | null;
  rivetVersion?: string;
  pluginName?: string;
  telemetryMode?: import('../config/telemetryPolicy').TelemetryMode;
};

export const serverRuntimeDirectory = (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): string =>
  channel === 'production'
    ? join(projectPath, '.rivet', 'cli')
    : join(projectPath, '.rivet', 'cli', channel);

export const handshakeFilePath = (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): string => join(serverRuntimeDirectory(projectPath, channel), 'server.json');

const lockFilePath = (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): string => join(serverRuntimeDirectory(projectPath, channel), 'server.lock');

const OWNER_ONLY_FILE_MODE = 0o600;

export const writeHandshake = (
  handshake: ServerHandshake,
  channel: InstallationChannel = installationChannel(),
): void => {
  const filePath = handshakeFilePath(handshake.projectPath, channel);
  mkdirSync(dirname(filePath), { recursive: true });
  writeFileAtomicSync(filePath, JSON.stringify(handshake), {
    mode: OWNER_ONLY_FILE_MODE,
  });
};

export type HandshakeReadResult =
  | { status: 'found'; handshake: ServerHandshake }
  | { status: 'missing' }
  | { status: 'invalid' };

export const readHandshakeResult = (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): HandshakeReadResult => {
  const filePath = handshakeFilePath(projectPath, channel);
  try {
    const parsed = JSON.parse(
      readFileSync(filePath, 'utf8'),
    ) as ServerHandshake;
    if (parsed.version !== CLI_HANDSHAKE_VERSION) {
      return { status: 'invalid' };
    }
    if (
      typeof parsed.pid !== 'number' ||
      !Number.isInteger(parsed.pid) ||
      parsed.pid <= 0 ||
      typeof parsed.rivetPort !== 'number' ||
      !Number.isInteger(parsed.rivetPort) ||
      parsed.rivetPort <= 0
    ) {
      return { status: 'invalid' };
    }
    return { status: 'found', handshake: parsed };
  } catch (error) {
    if (errnoCode(error) === 'ENOENT') {
      return { status: 'missing' };
    }
    log.debug(`Unreadable CLI handshake at ${filePath}`, error);
    return { status: 'invalid' };
  }
};

export const readHandshake = (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): ServerHandshake | null => {
  const result = readHandshakeResult(projectPath, channel);
  return result.status === 'found' ? result.handshake : null;
};

export const removeHandshake = (projectPath: string, pid: number): void => {
  const existing = readHandshake(projectPath);
  if (!existing || existing.pid !== pid) {
    return;
  }
  try {
    unlinkSync(handshakeFilePath(projectPath));
  } catch {}
};

export { isPidAlive };

export type StartLock = {
  holdForProcess: (
    pid: number,
    phase?: 'starting' | 'retiring',
  ) => Promise<void>;
  release: () => Promise<void>;
};

const RuntimeOwnerSchema = z.object({
  pid: z.number().int().positive(),
  token: z.string().uuid(),
  phase: z.enum(['active', 'starting', 'retiring']),
});

const fileOwnerCanWrite = (
  projectPath: string,
  channel: InstallationChannel,
): boolean => {
  try {
    const [owner] = readFileSync(
      lockFilePath(projectPath, channel),
      'utf8',
    ).split('\n');
    const pid = Number(owner);
    return !Number.isInteger(pid) || pid <= 0 || isPidAlive(pid);
  } catch (error) {
    return errnoCode(error) !== 'ENOENT';
  }
};

const withRuntimeOwnership = async <T>(
  directory: string,
  operation: (records: ProjectRuntimeRecords) => T,
): Promise<T> => {
  const records = await ProjectRuntimeRecords.open(directory);
  try {
    return records.transaction(() => operation(records));
  } finally {
    records.close();
  }
};

export const isServerStartInProgress = async (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): Promise<boolean> => {
  if (fileOwnerCanWrite(projectPath, channel)) return true;
  const directory = serverRuntimeDirectory(projectPath, channel);
  if (!existsSync(join(directory, 'lifecycle.sqlite'))) return false;
  return withRuntimeOwnership(directory, (records) => {
    const row = records.read();
    return row !== null && isPidAlive(RuntimeOwnerSchema.parse(row).pid);
  });
};

export const releaseReadyStartLock = async (
  projectPath: string,
  pid: number,
): Promise<void> => {
  await withRuntimeOwnership(serverRuntimeDirectory(projectPath), (records) => {
    const row = records.read();
    if (row) RuntimeOwnerSchema.parse(row);
    records.releaseReady(pid);
  });
};

export const acquireStartLock = async (
  projectPath: string,
  channel: InstallationChannel = installationChannel(),
): Promise<StartLock | null> => {
  const directory = serverRuntimeDirectory(projectPath, channel);
  const token = await withRuntimeOwnership(directory, (records) => {
    if (fileOwnerCanWrite(projectPath, channel)) return null;
    const row = records.read();
    if (row && isPidAlive(RuntimeOwnerSchema.parse(row).pid)) return null;
    const token = randomUUID();
    records.assign({ pid: process.pid, token, phase: 'active' });
    return token;
  });
  if (token === null) return null;
  return {
    holdForProcess: async (pid, phase = 'starting') => {
      const owner = RuntimeOwnerSchema.parse({ pid, phase, token });
      await withRuntimeOwnership(directory, (records) =>
        records.transfer(owner),
      );
    },
    release: async () => {
      await withRuntimeOwnership(directory, (records) =>
        records.release(token),
      );
    },
  };
};
